test('price bounds are inclusive on both ends', () => {
  const items = sampleCatalog();
  // prices: 5, 12.5, 0, 99, 12
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 5, maxPrice: 12 })), ['1', '5']);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 0, maxPrice: 0 })), ['3']);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 12.5, maxPrice: 12.5 })), ['2']);
});

test('minPrice default of 0 includes free items but excludes hypothetical negatives', () => {
  const items = [
    { id: 'neg', name: 'Refunded thing', price: -1 }, // data anomaly, bounds only are validated
