  assert.deepEqual(ids(searchCatalog(items, { query: 'red', minPrice: 1, maxPrice: 10 })), ['1']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'red', maxPrice: 1 })), ['3']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'red', minPrice: 50 })), []);
