test('stable ordering: duplicate-priority input keeps original relative order', () => {
  // Several items tie on name and price; only their ids differ. All match.
  const items = [
    { id: 'a-first', name: 'Widget', price: 10 },
    { id: 'b-second', name: 'widget', price: 10 },
    { id: 'c-third', name: 'WIDGET', price: 10 },
    { id: 'skip', name: 'Gizmo', price: 10 },
    { id: 'd-fifth', name: 'WiDgEt', price: 10 },
