 * @returns {Array<{id: string, name: string, price: number}>} new array of
 *   matching items, in original input order
 */
export function searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {}) {
  if (!Array.isArray(items)) {
