import test from 'node:test';
import assert from 'node:assert/strict';

import { parseCatalog } from '../src/csv.mjs';

const HEADER = 'id,name,price';

test('parses a simple single-row catalog with correct types', () => {
  const items = parseCatalog(`${HEADER}\n1,Widget,9.99\n`);
  assert.equal(items.length, 1);
  assert.equal(typeof items[0].id, 'string');
  assert.equal(typeof items[0].name, 'string');
  assert.equal(typeof items[0].price, 'number');
  assert.deepEqual(items, [{ id: '1', name: 'Widget', price: 9.99 }]);
});

test('returns plain objects with exactly the id/name/price keys', () => {
  const items = parseCatalog(`${HEADER}\n7,Bolt,0.5`);
  assert.deepEqual(Object.keys(items[0]).sort(), ['id', 'name', 'price']);
});

test('preserves row order across multiple rows', () => {
  const items = parseCatalog(`${HEADER}\na,X,1\nb,Y,2\nc,Z,3`);
  assert.deepEqual(
    items.map((i) => i.id),
    ['a', 'b', 'c']
  );
  assert.deepEqual(
    items.map((i) => i.price),
    [1, 2, 3]
  );
});

test('empty string input returns an empty array', () => {
  assert.deepEqual(parseCatalog(''), []);
});

test('input containing only line breaks / whitespace returns []', () => {
  assert.deepEqual(parseCatalog('\n'), []);
  assert.deepEqual(parseCatalog('\r\n\r\n'), []);
  assert.deepEqual(parseCatalog('   \n'), []);
});

test('header-only input (with or without trailing newline) returns []', () => {
  assert.deepEqual(parseCatalog(HEADER), []);
  assert.deepEqual(parseCatalog(`${HEADER}\n`), []);
  assert.deepEqual(parseCatalog(`${HEADER}\r\n`), []);
});

test('missing header row is rejected', () => {
  assert.throws(() => parseCatalog('1,Widget,9.99'), /header/i);
});

test('incorrect header row is rejected (case-sensitive, exact names)', () => {
  assert.throws(() => parseCatalog('ID,name,price\n1,X,1'), /header/i);
  assert.throws(() => parseCatalog('id,name\n1,X'), /header/i);
  assert.throws(() => parseCatalog('id,name,price,qty\n1,X,1,2'), /header/i);
});

test('quoted header fields are accepted (quotes stripped before compare)', () => {
  assert.deepEqual(parseCatalog('"id","name","price"'), []);
});

test('handles CRLF line endings throughout', () => {
  const items = parseCatalog(`${HEADER}\r\n1,Widget,9.99\r\n2,Gadget,5\r\n`);
  assert.deepEqual(items, [
    { id: '1', name: 'Widget', price: 9.99 },
    { id: '2', name: 'Gadget', price: 5 },
  ]);
});

test('handles lone CR as a record separator', () => {
  const items = parseCatalog(`${HEADER}\r1,Widget,9.99\r`);
  assert.deepEqual(items, [{ id: '1', name: 'Widget', price: 9.99 }]);
});

test('trailing newline does not create a phantom row', () => {
  const withNl = parseCatalog(`${HEADER}\n1,X,1\n`);
  const withoutNl = parseCatalog(`${HEADER}\n1,X,1`);
  assert.equal(withNl.length, 1);
  assert.deepEqual(withNl, withoutNl);
});

test('handles commas inside quoted fields', () => {
  const items = parseCatalog(`${HEADER}\n1,"Smith, John",9.99`);
  assert.equal(items[0].name, 'Smith, John');
});

test('handles escaped quotes ("") inside quoted fields', () => {
  const items = parseCatalog(`${HEADER}\n1,"He said ""hi""",2.50`);
  assert.equal(items[0].name, 'He said "hi"');
});

test('quoted fields may contain delimiters, quotes and newlines together', () => {
  const csv = `${HEADER}\n1,"a,""b"",\nc",3`;
  const items = parseCatalog(csv);
  assert.equal(items.length, 1);
  assert.equal(items[0].name, 'a,"b",\nc');
});

test('quoted empty field is preserved as empty string', () => {
  const items = parseCatalog(`${HEADER}\n1,"",0`);
  assert.equal(items[0].name, '');
  assert.equal(items[0].price, 0);
});

test('blank lines (and whitespace-only lines) are skipped anywhere', () => {
  const items = parseCatalog(`${HEADER}\n\n1,X,1\n   \n2,Y,2\n\n`);
  assert.deepEqual(items, [
    { id: '1', name: 'X', price: 1 },
    { id: '2', name: 'Y', price: 2 },
  ]);
});

test('unbalanced quote is rejected', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,"open,9.99`), /quote/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,"multi\nline,9.99`), /quote/i);
});

test('rows with wrong field count are rejected', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,Widget`), /expected 3 fields/);
  assert.throws(
    () => parseCatalog(`${HEADER}\n1,Widget,9.99,extra`),
    /expected 3 fields/
  );
  assert.throws(() => parseCatalog(`${HEADER}\n1`), /expected 3 fields/);
});

test('error for wrong field count mentions the record number', () => {
  assert.throws(
    () => parseCatalog(`${HEADER}\n1,X,1\n2,Y,2\nbad,row`),
    /record 4/
  );
});

test('non-numeric prices are rejected', () => {
  for (const bad of ['abc', '9.99usd', '1,5', '$5', '', ' ', '12 34']) {
    assert.throws(
      () => parseCatalog(`${HEADER}\n1,X,${bad}`),
      /price/i,
      `should reject price '${bad}'`
    );
  }
});

test('NaN / Infinity spellings are rejected as prices', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,NaN`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,Infinity`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,-Infinity`), /price/i);
});

test('non-finite prices (overflow) are rejected', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,1e999`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,1e+400`), /price/i);
});

test('negative prices are rejected', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,-1`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,-0.01`), /negative/i);
});

test('zero price is allowed', () => {
  const items = parseCatalog(`${HEADER}\n1,Free,0`);
  assert.equal(items[0].price, 0);
});

test('accepts integer, decimal and exponential price forms', () => {
  const items = parseCatalog(
    [HEADER, '1,a,5', '2,b,5.0', '3,c,.5', '4,d,2.', '5,e,+3', '6,f,1e2', '7,g,1E+2', '8,h,1.5e-3'].join(
      '\n'
    )
  );
  assert.deepEqual(
    items.map((i) => i.price),
    [5, 5.0, 0.5, 2, 3, 100, 100, 0.0015]
  );
});

test('surrounding whitespace in price field is tolerated, inner is not', () => {
  const items = parseCatalog(`${HEADER}\n1,X," 4.50 "`);
  assert.equal(items[0].price, 4.5);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,4 .50`), /price/i);
});

test('id and name fields are preserved verbatim (no trimming, no coercion)', () => {
  const items = parseCatalog(`${HEADER}\n 001 , pad me ,1`);
  assert.equal(items[0].id, ' 001 ');
  assert.equal(items[0].name, ' pad me ');
  const items2 = parseCatalog(`${HEADER}\n001,x,1`);
  assert.equal(items2[0].id, '001'); // stays a string, not 1
});

test('empty id/name are not treated as malformed (only price is validated)', () => {
  const items = parseCatalog(`${HEADER}\n,,0`);
  assert.deepEqual(items, [{ id: '', name: '', price: 0 }]);
});

test('lenient quote corner cases per documented interpretation', () => {
  // quote mid-field is literal
  const a = parseCatalog(`${HEADER}\nab"cd,e,f`);
  assert.equal(a[0].id, 'ab"cd');
  // content after closing quote is appended
