  for (const bad of ['abc', '9.99usd', '1,5', '$5', '', ' ', '12 34']) {
    assert.throws(
      () => parseCatalog(`${HEADER}\n1,X,${bad}`),
      /price/i,
      `should reject price '${bad}'`
    );
  }
});

test('NaN / Infinity spellings are rejected as prices', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,NaN`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,Infinity`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,-Infinity`), /price/i);
});

test('non-finite prices (overflow) are rejected', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,1e999`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,1e+400`), /price/i);
});

test('negative prices are rejected', () => {
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,-1`), /price/i);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,-0.01`), /negative/i);
});

test('zero price is allowed', () => {
  const items = parseCatalog(`${HEADER}\n1,Free,0`);
  assert.equal(items[0].price, 0);
});

test('accepts integer, decimal and exponential price forms', () => {
  const items = parseCatalog(
    [HEADER, '1,a,5', '2,b,5.0', '3,c,.5', '4,d,2.', '5,e,+3', '6,f,1e2', '7,g,1E+2', '8,h,1.5e-3'].join(
      '\n'
    )
  );
  assert.deepEqual(
    items.map((i) => i.price),
    [5, 5.0, 0.5, 2, 3, 100, 100, 0.0015]
  );
});

test('surrounding whitespace in price field is tolerated, inner is not', () => {
  const items = parseCatalog(`${HEADER}\n1,X," 4.50 "`);
  assert.equal(items[0].price, 4.5);
  assert.throws(() => parseCatalog(`${HEADER}\n1,X,4 .50`), /price/i);
});

test('id and name fields are preserved verbatim (no trimming, no coercion)', () => {
  const items = parseCatalog(`${HEADER}\n 001 , pad me ,1`);
  assert.equal(items[0].id, ' 001 ');
  assert.equal(items[0].name, ' pad me ');
  const items2 = parseCatalog(`${HEADER}\n001,x,1`);
  assert.equal(items2[0].id, '001'); // stays a string, not 1
});

test('empty id/name are not treated as malformed (only price is validated)', () => {
  const items = parseCatalog(`${HEADER}\n,,0`);
  assert.deepEqual(items, [{ id: '', name: '', price: 0 }]);
});

test('lenient quote corner cases per documented interpretation', () => {
  // quote mid-field is literal
  const a = parseCatalog(`${HEADER}\nab"cd,e,f`);
  assert.equal(a[0].id, 'ab"cd');
  // content after closing quote is appended
  const b = parseCatalog(`${HEADER}\n1,"b"x,2`);
  assert.equal(b[0].name, 'bx');
  // quote not at field start (after a space) is literal, field verbatim
  const c = parseCatalog(`${HEADER}\n1, "hi" ,2`);
  assert.equal(c[0].name, ' "hi" ');
});

test('non-string input throws TypeError', () => {
  for (const bad of [null, undefined, 42, {}, [], Buffer.from(HEADER)]) {
    assert.throws(() => parseCatalog(bad), TypeError);
  }
});

test('returns fresh arrays/objects on each call (no shared state)', () => {
  const csv = `${HEADER}\n1,X,1`;
  const a = parseCatalog(csv);
  const b = parseCatalog(csv);
  assert.notEqual(a, b);
  assert.notEqual(a[0], b[0]);
  assert.deepEqual(a, b);
});

test('realistic mixed document parses end to end', () => {
  const csv =
    'id,name,price\r\n' +
    'A-1,"Chair, wooden",12.50\r\n' +
    'A-2,"Lamp ""Sunrise""",7\r\n' +
    '\r\n' +
    'A-3,"Multi\nline rug",1e2\r\n';
  assert.deepEqual(parseCatalog(csv), [
    { id: 'A-1', name: 'Chair, wooden', price: 12.5 },
    { id: 'A-2', name: 'Lamp "Sunrise"', price: 7 },
    { id: 'A-3', name: 'Multi\nline rug', price: 100 },
  ]);
});
