// src/search.mjs
// searchCatalog — implements the public contract from README.md.
//
// "Invalid bounds" interpretation (kept consistent with tests/search.test.mjs):
//   * query (when provided) must be a string; otherwise TypeError.
//   * minPrice / maxPrice must be actual numbers (typeof === 'number') and
//     not NaN; anything else (undefined-with-explicit?, string, null, NaN)
//     throws TypeError. Note: omitting a bound uses the documented default.
//   * bounds must be non-negative (negative prices are meaningless in this
//     catalog, mirroring src/csv.mjs rejecting negative prices) — otherwise
//     RangeError.
//   * minPrice must be finite. maxPrice may be Infinity (the documented
//     default), but -Infinity is rejected (negative).
//   * minPrice must not exceed maxPrice; otherwise RangeError.
//
// Matching semantics:
//   * Case-insensitive substring match of query against item.name
//     (empty query '' matches every item, since '' is a substring of any
//     string).
//   * Price bounds are inclusive: minPrice <= item.price <= maxPrice.
//   * The result preserves the original relative order of matching items
//     (stable ordering, including for duplicate-priority inputs).
//   * The input array and its items are never mutated or reordered; a new
//     array containing the SAME item objects is returned.

export function searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {}) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }
  if (typeof query !== 'string') {
    throw new TypeError('query must be a string');
  }
  validateBound('minPrice', minPrice, { requireFinite: true });
  validateBound('maxPrice', maxPrice, { requireFinite: false });
  if (minPrice > maxPrice) {
    throw new RangeError(`invalid bounds: minPrice (${minPrice}) > maxPrice (${maxPrice})`);
  }
  const needle = query.toLowerCase();
  return items.filter((item) =>
    String(item.name).toLowerCase().includes(needle) &&
    item.price >= minPrice &&
    item.price <= maxPrice
  );
}

function validateBound(name, value, { requireFinite }) {
  if (typeof value !== 'number' || Number.isNaN(value)) {
    throw new TypeError(`${name} must be a number (got ${...})`);
  }
  if (value < 0) throw new RangeError(`${name} must be non-negative`);
  if (requireFinite && !Number.isFinite(value)) throw new RangeError(`${name} must be finite`);
}
```

