import test from 'node:test';
import assert from 'node:assert/strict';

import { searchCatalog } from '../src/search.mjs';

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const sampleCatalog = () => [
  { id: '1', name: 'Red Widget', price: 5 },
  { id: '2', name: 'Blue Gadget', price: 12.5 },
  { id: '3', name: 'red cherry', price: 0 },
  { id: '4', name: 'Cherub', price: 99 },
  { id: '5', name: 'Green Apple', price: 12 },
];

const ids = (rows) => rows.map((r) => r.id);

// ---------------------------------------------------------------------------
// Basic search semantics
// ---------------------------------------------------------------------------

test('empty query (default) returns every item, in input order', () => {
  const items = sampleCatalog();
  const result = searchCatalog(items);
  assert.deepEqual(ids(result), ['1', '2', '3', '4', '5']);
});

test('explicit empty-string query also matches everything', () => {
  const items = sampleCatalog();
  assert.deepEqual(ids(searchCatalog(items, { query: '' })), ['1', '2', '3', '4', '5']);
});

test('missing options argument and empty options object both use defaults', () => {
  const items = sampleCatalog();
  assert.deepEqual(ids(searchCatalog(items, {})), ids(items));
  // Explicit `undefined` keys fall back to destructuring defaults.
  assert.deepEqual(
    ids(searchCatalog(items, { query: undefined, minPrice: undefined, maxPrice: undefined })),
    ids(items)
  );
});

test('substring match is case-insensitive on name', () => {
  const items = sampleCatalog();
  assert.deepEqual(ids(searchCatalog(items, { query: 'RED' })), ['1', '3']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'red' })), ['1', '3']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'ReD' })), ['1', '3']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'gAdGeT' })), ['2']);
});

test('match is substring, not whole-word or prefix-only', () => {
  const items = sampleCatalog();
  assert.deepEqual(ids(searchCatalog(items, { query: 'cher' })), ['3', '4']); // cherry + Cherub
  assert.deepEqual(ids(searchCatalog(items, { query: 'ed wid' })), ['1']);
});

test('query matching a name with different casing still matches', () => {
  const items = [{ id: 'x', name: 'MiXeD CaSe ItEm', price: 1 }];
  assert.deepEqual(ids(searchCatalog(items, { query: 'mixed case' })), ['x']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'ITEM' })), ['x']);
});

test('no match returns an empty array', () => {
  const items = sampleCatalog();
  const result = searchCatalog(items, { query: 'zebra' });
  assert.ok(Array.isArray(result));
  assert.equal(result.length, 0);
});

test('empty input array returns empty result', () => {
  assert.deepEqual(searchCatalog([]), []);
  assert.deepEqual(searchCatalog([], { query: 'anything', minPrice: 1, maxPrice: 2 }), []);
});

// ---------------------------------------------------------------------------
// Price bounds (inclusive)
// ---------------------------------------------------------------------------

test('price bounds are inclusive on both ends', () => {
  const items = sampleCatalog();
  // prices: 5, 12.5, 0, 99, 12
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 5, maxPrice: 12 })), ['1', '5']);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 0, maxPrice: 0 })), ['3']);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 12.5, maxPrice: 12.5 })), ['2']);
});

test('minPrice default of 0 includes free items but excludes hypothetical negatives', () => {
  const items = [
    { id: 'neg', name: 'Refunded thing', price: -1 }, // data anomaly, bounds only are validated
    { id: 'zero', name: 'Free sample', price: 0 },
    { id: 'pos', name: 'Paid sample', price: 0.01 },
  ];
  assert.deepEqual(ids(searchCatalog(items)), ['zero', 'pos']);
});

test('maxPrice default of Infinity imposes no upper bound', () => {
  const items = sampleCatalog();
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 12 })), ['2', '4', '5']);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 12, maxPrice: Infinity })), ['2', '4', '5']);
});

test('query and price filters combine (logical AND)', () => {
  const items = sampleCatalog();
  // 'red' matches ids 1 (price 5) and 3 (price 0)
  assert.deepEqual(ids(searchCatalog(items, { query: 'red', minPrice: 1, maxPrice: 10 })), ['1']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'red', maxPrice: 1 })), ['3']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'red', minPrice: 50 })), []);
});

test('fractional bounds work like integer ones', () => {
  const items = sampleCatalog();
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 4.999, maxPrice: 5.001 })), ['1']);
});

// ---------------------------------------------------------------------------
// Order preservation (stable ordering)
// ---------------------------------------------------------------------------

test('stable ordering: duplicate-priority input keeps original relative order', () => {
  // Several items tie on name and price; only their ids differ. All match.
  const items = [
    { id: 'a-first', name: 'Widget', price: 10 },
    { id: 'b-second', name: 'widget', price: 10 },
    { id: 'c-third', name: 'WIDGET', price: 10 },
    { id: 'skip', name: 'Gizmo', price: 10 },
    { id: 'd-fifth', name: 'WiDgEt', price: 10 },
  ];
  assert.deepEqual(ids(searchCatalog(items, { query: 'widget' })), [
    'a-first',
    'b-second',
    'c-third',
    'd-fifth',
  ]);
});

test('order is preserved even when matches are interleaved with non-matches', () => {
  const items = [
    { id: '1', name: 'nope', price: 1 },
    { id: '2', name: 'target x', price: 1 },
    { id: '3', name: 'nope again', price: 1 },
    { id: '4', name: 'TARGET y', price: 1 },
    { id: '5', name: 'target z', price: 1000 }, // out of price range
    { id: '6', name: 'target w', price: 1 },
  ];
  assert.deepEqual(ids(searchCatalog(items, { query: 'target', maxPrice: 100 })), ['2', '4', '6']);
});

// ---------------------------------------------------------------------------
// Non-mutation of input
// ---------------------------------------------------------------------------

test('input array and items are never mutated or reordered (snapshot deep-compare)', () => {
  const items = sampleCatalog();
  // Extra adversarial content: duplicates, unusual values, nested-free objects.
  items.push({ id: 'dup-1', name: 'Red Widget', price: 5 });
  items.push({ id: 'dup-2', name: 'Red Widget', price: 5 });

  const snapshot = structuredClone(items); // deep copy taken BEFORE the call

  const result = searchCatalog(items, { query: 'red', minPrice: 1, maxPrice: 10 });

  // Deep-compare the whole input against the pre-call snapshot: proves no
  // element was mutated, reordered, added, or removed.
  assert.deepEqual(items, snapshot);

  // The result is a NEW array, never the input array itself...
  assert.notEqual(result, items);
  assert.notEqual(result, snapshot);
  // ...containing the SAME (untouched) item objects, in original order.
  assert.equal(result.length, 2);
  assert.equal(result[0], items[0]); // reference equality with original item
  assert.equal(result[1], items[5]);
  assert.deepEqual(ids(result), ['1', 'dup-1']);

  // Snapshot again after: repeated calls also leave input pristine.
  searchCatalog(items);
  searchCatalog(items, { query: 'GADGET' });
  assert.deepEqual(items, snapshot);
});

test('returned items are the original objects, not copies (so mutation would have been observable)', () => {
  const items = sampleCatalog();
  const result = searchCatalog(items, { query: 'Cherub' });
  assert.equal(result.length, 1);
  assert.equal(result[0], items[3]); // same reference
});

