test('non-array items throws TypeError', () => {
  assert.throws(() => searchCatalog(undefined), TypeError);
  assert.throws(() => searchCatalog('not an array'), TypeError);
  assert.throws(() => searchCatalog({ 0: { name: 'x', price: 1 }, length: 1 }), TypeError);
});

test('non-string query throws TypeError', () => {
  const items = sampleCatalog();
  assert.throws(() => searchCatalog(items, { query: 5 }), TypeError);
  assert.throws(() => searchCatalog(items, { query: null }), TypeError);
  assert.throws(() => searchCatalog(items, { query: /red/ }), TypeError);
});

test('minPrice > maxPrice throws RangeError', () => {
  const items = sampleCatalog();
  assert.throws(() => searchCatalog(items, { minPrice: 10, maxPrice: 5 }), RangeError);
  assert.throws(() => searchCatalog(items, { minPrice: 1, maxPrice: 0.999 }), RangeError);
});

test('non-number or NaN bounds throw TypeError', () => {
  const items = sampleCatalog();
  for (const bad of ['10', true, {}, [], Symbol.iterator /* any symbol */, 12n]) {
    assert.throws(() => searchCatalog(items, { minPrice: bad }), TypeError, `minPrice=${String(bad)}`);
    assert.throws(() => searchCatalog(items, { maxPrice: bad }), TypeError, `maxPrice=${String(bad)}`);
  }
  assert.throws(() => searchCatalog(items, { minPrice: NaN }), TypeError);
  assert.throws(() => searchCatalog(items, { maxPrice: NaN }), TypeError);
});

test('negative bounds throw RangeError (catalog has no negative prices)', () => {
  const items = sampleCatalog();
  assert.throws(() => searchCatalog(items, { minPrice: -1 }), RangeError);
  assert.throws(() => searchCatalog(items, { maxPrice: -1 }), RangeError);
  assert.throws(() => searchCatalog(items, { maxPrice: -Infinity }), RangeError);
  assert.throws(() => searchCatalog(items, { minPrice: -0.0001 }), RangeError);
});

test('non-finite minPrice throws RangeError, but Infinity maxPrice is allowed', () => {
  const items = sampleCatalog();
  assert.throws(() => searchCatalog(items, { minPrice: Infinity }), RangeError);
  assert.doesNotThrow(() => searchCatalog(items, { maxPrice: Infinity })); // documented default
  assert.doesNotThrow(() => searchCatalog(items, { minPrice: 0, maxPrice: Number.MAX_VALUE }));
});

test('invalid calls do not mutate the input either', () => {
  const items = sampleCatalog();
  const snapshot = structuredClone(items);
  for (const attempt of [
    () => searchCatalog(items, { minPrice: 10, maxPrice: 5 }),
    () => searchCatalog(items, { minPrice: NaN }),
    () => searchCatalog(items, { maxPrice: -3 }),
    () => searchCatalog(items, { query: 42 }),
  ]) {
    assert.throws(attempt);
  }
  assert.deepEqual(items, snapshot);
});
