function validateBound(name, value, requireFinite) {
  if (typeof value !== 'number' || Number.isNaN(value)) {
    const shown = typeof value === 'number' ? String(value) : `${typeof value}: ${String(value)}`;
    throw new TypeError(`${name} must be a number (got ${shown})`);
  }
  if (value < 0) {
    throw new RangeError(`${name} must be non-negative (got ${value})`);
  }
  if (requireFinite && !Number.isFinite(value)) {
    throw new RangeError(`${name} must be finite (got ${value})`);
  }
}

/**
 * Search/filter a catalog.
 * @param {Array<{id: string, name: string, price: number}>} items
 * @param {{query?: string, minPrice?: number, maxPrice?: number}} [options]
 * @returns {Array<{id: string, name: string, price: number}>} new array of
 *   matching items, in original input order
 */
export function searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {}) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }
  if (typeof query !== 'string') {
    throw new TypeError(`query must be a string (got ${typeof query})`);
  }
  validateBound('minPrice', minPrice, /* requireFinite */ true);
  validateBound('maxPrice', maxPrice, /* requireFinite */ false);
  if (minPrice > maxPrice) {
    throw new RangeError(`invalid price bounds: minPrice (${minPrice}) > maxPrice (${maxPrice})`);
  }

  const needle = query.toLowerCase();
  // Array.prototype.filter returns a NEW array and preserves encounter
  // order; it neither mutates `items` nor its elements.
  return items.filter((item) =>
    String(item.name).toLowerCase().includes(needle) &&
    item.price >= minPrice &&
    item.price <= maxPrice
  );
}
